//! Direct WebAssembly backend for Titan's portable numeric bytecode.
use thiserror::Error;
use titan_codegen::{CompiledModule,Op};
use wasm_encoder::{CodeSection,ExportKind,ExportSection,Function,FunctionSection,Instruction,Module,TypeSection,ValType};
#[derive(Error,Debug)]pub enum WasmError{#[error("invalid module entry point")]Entry,#[error("function '{function}' uses unsupported WebAssembly operation: {operation}")]Unsupported{function:String,operation:String},#[error("local count underflow in function '{0}'")]Locals(String)}
pub fn compile(module:&CompiledModule)->Result<Vec<u8>,WasmError>{if module.entry>=module.functions.len(){return Err(WasmError::Entry)}let mut output=Module::new();let mut types=TypeSection::new();for function in &module.functions{types.function(vec![ValType::I64;function.arity],vec![ValType::I64]);}output.section(&types);let mut functions=FunctionSection::new();for index in 0..module.functions.len(){functions.function(index as u32);}output.section(&functions);let mut exports=ExportSection::new();exports.export("main",ExportKind::Func,module.entry as u32);for(index,function)in module.functions.iter().enumerate(){if function.name!="main"&&!function.name.starts_with('<'){exports.export(&function.name,ExportKind::Func,index as u32);}}output.section(&exports);let mut code=CodeSection::new();for function in &module.functions{let extra=function.locals.checked_sub(function.arity).ok_or_else(||WasmError::Locals(function.name.clone()))?;let locals=if extra==0{Vec::new()}else{vec![(extra as u32,ValType::I64)]};let mut body=Function::new(locals);let mut returned=false;for operation in &function.code{match operation{Op::PushInt(value)=>{body.instruction(&Instruction::I64Const(*value));},Op::PushBool(value)=>{body.instruction(&Instruction::I64Const(i64::from(*value)));},Op::PushNil=>{body.instruction(&Instruction::I64Const(0));},Op::PushLocal(index)=>{body.instruction(&Instruction::LocalGet(*index as u32));},Op::StoreLocal(index)=>{body.instruction(&Instruction::LocalSet(*index as u32));},Op::Pop=>{body.instruction(&Instruction::Drop);},Op::Add=>{body.instruction(&Instruction::I64Add);},Op::Sub=>{body.instruction(&Instruction::I64Sub);},Op::Mul=>{body.instruction(&Instruction::I64Mul);},Op::Div=>{body.instruction(&Instruction::I64DivS);},Op::Mod=>{body.instruction(&Instruction::I64RemS);},Op::Neg=>{body.instruction(&Instruction::I64Const(-1));body.instruction(&Instruction::I64Mul)},Op::BitAnd=>{body.instruction(&Instruction::I64And);},Op::BitOr=>{body.instruction(&Instruction::I64Or);},Op::BitXor=>{body.instruction(&Instruction::I64Xor);},Op::BitNot=>{body.instruction(&Instruction::I64Const(-1));body.instruction(&Instruction::I64Xor)},Op::Eq=>comparison(&mut body,Instruction::I64Eq),Op::Neq=>comparison(&mut body,Instruction::I64Ne),Op::Lt=>comparison(&mut body,Instruction::I64LtS),Op::Gt=>comparison(&mut body,Instruction::I64GtS),Op::Lte=>comparison(&mut body,Instruction::I64LeS),Op::Gte=>comparison(&mut body,Instruction::I64GeS),Op::Call{function,..}=>{body.instruction(&Instruction::Call(*function as u32));},Op::Ret=>{body.instruction(&Instruction::Return);returned=true},Op::Nop=>{body.instruction(&Instruction::Nop);},Op::Halt=>{body.instruction(&Instruction::Return);returned=true},other=>return Err(WasmError::Unsupported{function:function.name.clone(),operation:format!("{other:?}")})};}if !returned{body.instruction(&Instruction::I64Const(0));}body.instruction(&Instruction::End);code.function(&body);}output.section(&code);Ok(output.finish())}
fn comparison(function:&mut Function,instruction:Instruction<'_>){function.instruction(&instruction);function.instruction(&Instruction::I64ExtendI32U);}
#[cfg(test)]mod tests{use super::*;use titan_codegen::{BytecodeFunc,CompiledModule};#[test]fn emits_valid_executable_wasm(){let module=CompiledModule{functions:vec![BytecodeFunc{name:"main".into(),source_file:Some("main.titan".into()),arity:0,captures:0,locals:0,max_stack:4,code:vec![Op::PushInt(40),Op::PushInt(2),Op::Add,Op::Ret],debug_locations:vec![None;4]}],entry:0,string_table:Vec::new()};let wasm=compile(&module).unwrap();wasmparser::Validator::new().validate_all(&wasm).unwrap();assert_eq!(&wasm[..4],b"\0asm");}#[test]fn rejects_unsupported_runtime_values(){let mut module=CompiledModule{functions:vec![BytecodeFunc{name:"main".into(),source_file:None,arity:0,captures:0,locals:0,max_stack:2,code:vec![Op::PushStr(0),Op::Ret],debug_locations:vec![None;2]}],entry:0,string_table:vec!["x".into()]};assert!(compile(&module).is_err());module.functions[0].code=vec![Op::PushInt(1),Op::Ret];assert!(compile(&module).is_ok());}}
